package com.jian.scrcpy.server;import com.jian.scrcpy.adb.Adb;import java.nio.file.*;import java.util.*;
public final class ServerLauncher implements AutoCloseable{public static final String REMOTE="/data/local/tmp/scrcpy-server.jar";private final Adb adb;private final ScrcpyOptions o;private Process process;public ServerLauncher(Adb a,ScrcpyOptions o){adb=a;this.o=o;}public String socketName(){return "scrcpy_%08x".formatted(o.scid());}public void start(Path jar)throws Exception{adb.push(jar,REMOTE);adb.forward(o.localPort(),socketName());var a=new ArrayList<String>();Collections.addAll(a,"CLASSPATH="+REMOTE,"app_process","/","com.genymobile.scrcpy.Server","5.0.1","scid=%08x".formatted(o.scid()),"log_level=info","tunnel_forward=true");if(!o.video())a.add("video=false");if(!o.audio())a.add("audio=false");if(!o.control())a.add("control=false");process=adb.shellAsync(a);}public void close(){if(process!=null)process.destroy();try{adb.removeForward(o.localPort());}catch(Exception ignored){}}}